/**
 * Magic symbols as icons for Icon(), traced from the Mana font (Andrew Gioia, SIL OFL 1.1).
 * Each path is already centered in a square box.
 */
object ManaIcons {
    private fun icon(name: String, side: Float, path: String): ImageVector =
        ImageVector.Builder(name = name, defaultWidth = 24.dp, defaultHeight = 24.dp, viewportWidth = side, viewportHeight = side)
            .addPath(addPathNodes(path), fill = SolidColor(Color.Black))
            .build()

